def _blocked_wy_backtransform(
    vectors, reflectors, taus, block, triangular_inverse=False,
    panel_ready=False, packed_panels=False, inplace_apply=False,
    factor_v=False
):
    n = vectors.shape[-1]
    previous_precision = torch.get_float32_matmul_precision()
    torch.set_float32_matmul_precision("highest")
    for start in reversed(range(0, n - 2, block)):
        width = min(block, n - 2 - start)
        tail = start + 1
        if packed_panels:
            panel_offset = 0
            for prior_start in range(0, start, block):
                prior_width = min(block, n - 2 - prior_start)
                panel_offset += (
                    vectors.shape[0] * (n - prior_start - 1) * prior_width
                )
            panel_size = vectors.shape[0] * (n - tail) * width
            panel = reflectors.narrow(
                0, panel_offset, panel_size
            ).view(vectors.shape[0], n - tail, width)
        else:
            panel = reflectors[:, tail:, start : start + width]
        if panel_ready:
            v = panel
        else:
            v = torch.tril(panel, diagonal=-1)
            v = v + torch.eye(
                v.shape[1], width, dtype=v.dtype, device=v.device
            )
        gram = torch.bmm(v.transpose(1, 2), v)
        panel_taus = taus[:, start : start + width]
        if triangular_inverse:
            t = _compact_wy_triangular(
                gram, panel_taus, invert=not factor_v
            )
        else:
            t = _ext.compact_wy_t(gram, panel_taus.contiguous())
        panel_vectors = vectors[:, tail:, :]
        updated = _apply_wy_left(
            panel_vectors, v, t, transpose=False, inplace=inplace_apply,
            factor_v=factor_v
        )
        if not inplace_apply:
            vectors[:, tail:, :] = updated
    torch.set_float32_matmul_precision(previous_precision)
    return vectors


